    private Unicode17Data() {
        // Utility class.
    }

    static boolean isZeroWidthCategory(final int codePoint) {
        return isInRanges(codePoint, ZERO_WIDTH_CATEGORY_RANGES);
    }

    static boolean isMark(final int codePoint) {
        return isInRanges(codePoint, MarkData.MARK_RANGES);
    }

    static boolean isCased(final int codePoint) {
        return isInRanges(codePoint, CaseData.CASED_RANGES);
    }

    static boolean isCaseIgnorable(final int codePoint) {
        return isInRanges(codePoint, CaseData.CASE_IGNORABLE_RANGES);
    }

    static byte graphemeBreakProperty(final int codePoint) {
        return propertyOf(codePoint, GRAPHEME_BREAK_RANGES, GCB_OTHER);
    }

    static byte indicConjunctBreakProperty(final int codePoint) {
        return propertyOf(codePoint, INDIC_CONJUNCT_BREAK_RANGES, INCB_NONE);
    }

    static boolean isEastAsianWideOrFullwidth(final int codePoint) {
        return isInRanges(codePoint, EAST_ASIAN_WIDE_OR_FULLWIDTH_RANGES);
    }

    static boolean isEastAsianAmbiguous(final int codePoint) {
        return isInRanges(codePoint, EAST_ASIAN_AMBIGUOUS_RANGES);
    }

    static boolean isEmojiPresentation(final int codePoint) {
        return isInRanges(codePoint, EMOJI_PRESENTATION_RANGES);
    }

    static boolean isEmojiVariationBase(final int codePoint) {
        return isInRanges(codePoint, EMOJI_VARIATION_BASE_RANGES);
    }

    static boolean isExtendedPictographic(final int codePoint) {
        return isInRanges(codePoint, EXTENDED_PICTOGRAPHIC_RANGES);
    }

    private static byte propertyOf(final int codePoint, final int[] ranges, final byte defaultValue) {
        int low = 0;
        int high = ranges.length / 3 - 1;

        while (low <= high) {
            final int middle = (low + high) >>> 1;
            final int rangeIndex = middle * 3;

            if (codePoint < ranges[rangeIndex]) {
                high = middle - 1;
            } else if (codePoint > ranges[rangeIndex + 1]) {
                low = middle + 1;
            } else {
                return (byte) ranges[rangeIndex + 2];
            }
        }

        return defaultValue;
    }

    private static boolean isInRanges(final int codePoint, final int[] ranges) {
        int low = 0;
        int high = ranges.length / 2 - 1;

        while (low <= high) {
            final int middle = (low + high) >>> 1;
            final int rangeIndex = middle * 2;

            if (codePoint < ranges[rangeIndex]) {
                high = middle - 1;
            } else if (codePoint > ranges[rangeIndex + 1]) {
                low = middle + 1;
            } else {
                return true;
            }
        }

        return false;
    }
